package com.giftplatform.celebrationplanning;
import java.time.LocalDate;
import java.util.List;
public final class CelebrationKeepsake {
 private CelebrationKeepsake(){}
 public record Message(String name,String text){}
 static String html(String text){return text==null?"":text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 public static String render(String title,LocalDate date,List<Message> messages,boolean truncated){StringBuilder out=new StringBuilder("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Our celebration keepsake</title><style>body{background:#faf7f0;color:#263d35;font:18px/1.7 Georgia,serif;margin:0}main{max-width:780px;margin:auto;padding:48px 24px}header{text-align:center;padding:40px 0}h1{font-size:44px;line-height:1.2}article{background:white;border:1px solid #ded8c9;padding:28px;margin:24px 0;break-inside:avoid}blockquote{white-space:pre-wrap;margin:0}footer{text-align:right;font-style:italic}.hint{font:14px/1.6 sans-serif;color:#58675e}@media print{body{background:white}.hint{display:none}main{padding:0}header{break-after:page}article{border:0;border-bottom:1px solid #ddd}}</style><main><header><p>COLLECTED WITH LOVE</p><h1>");out.append(html(title)).append("</h1><p>").append(date==null?"A moment to remember":date).append("</p><p>Kind words. Familiar names. A little piece of this day, forever.</p><p class=\"hint\">A private text keepsake of approved wishes. Use your browser’s Print command to save as PDF or print. Downloaded copies remain on your device after access is revoked.</p></header>");if(messages.isEmpty())out.append("<p>Your approved wishes will become a keepsake here.</p>");for(Message m:messages)out.append("<article><blockquote>").append(html(m.text())).append("</blockquote><footer>With love, ").append(html(m.name())).append("</footer></article>");if(truncated)out.append("<p>This keepsake includes the first 500 approved wishes. Your complete collection remains in the private album.</p>");return out.append("</main></html>").toString();}
}
